1	import { Block, Text } from "@prototyp/skeletor";
2	import {
3	  type EventTimelineItem,
4	  type ImageMessageContent,
5	  MessageType_Tags,
6	  MsgLikeKind_Tags,
7	  type RoomInterface,
8	  TimelineItemContent_Tags,
9	  type VideoMessageContent,
10	} from "@unomed/react-native-matrix-sdk";
11	import { useSetAtom } from "jotai";
12	import { getEventId } from "modules/matrix-client/utils";
13	import { TimelineAtoms } from "modules/timeline/jotai";
14	import { type FC, useEffect, useMemo, useState } from "react";
15	import { StyleSheet } from "react-native";
16	import { useMediaTimeline } from "screens/room-media/hooks";
17	import { Button } from "shared/components";
18	import { Colors, TextSize } from "shared/styles";
19	import { FilesList } from "../files-list";
20	import { MediaList } from "../media-list";
21	
22	interface Props {
23	  room: RoomInterface;
24	}
25	
26	type Tab = "media" | "files";
27	
28	function isMediaItem(event: EventTimelineItem): boolean {
29	  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
30	    const kind = event.content.inner.content.kind;
31	    if (kind?.tag === MsgLikeKind_Tags.Message) {
32	      const tag = kind.inner.content.msgType?.tag;
33	      return tag === MessageType_Tags.Image || tag === MessageType_Tags.Video;
34	    }
35	  }
36	  return false;
37	}
38	
39	function isFileItem(event: EventTimelineItem): boolean {
40	  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
41	    const kind = event.content.inner.content.kind;
42	    if (kind?.tag === MsgLikeKind_Tags.Message) {
43	      const tag = kind.inner.content.msgType?.tag;
44	      return tag === MessageType_Tags.File || tag === MessageType_Tags.Audio;
45	    }
46	  }
47	  return false;
48	}
49	
50	export const MediaGallery: FC<Props> = ({ room }) => {
51	  const { mediaItems: allItems, loading, paginating, reachedStart, loadMore } = useMediaTimeline({
52	    room,
53	    roomId: room.id(),
54	  });
55	  const [activeTab, setActiveTab] = useState<Tab>("media");
56	  const mediaItems = useMemo(() => allItems.filter(isMediaItem), [allItems]);
57	  const fileItems = useMemo(() => allItems.filter(isFileItem), [allItems]);
58	  const isMediaEmpty = !mediaItems.length;
59	  const isFileEmpty = !fileItems.length;
60	  const setMediaViewerPayload = useSetAtom(TimelineAtoms.mediaViewerPayload);
61	
62	  // Auto-paginate until all history is loaded or the component unmounts.
63	  useEffect(() => {
64	    if (!loading && !paginating && !reachedStart) loadMore();
65	  }, [loading, paginating, reachedStart, loadMore]);
66	
67	  const handleSetActiveImageUri = (
68	    _uri: string | null,
69	    type?: "image" | "video",
70	    _content?: ImageMessageContent | VideoMessageContent,
71	    event?: EventTimelineItem,
72	  ) => {
73	    if (!type || !event) return;
74	    const eventId = getEventId(event);
75	    if (!eventId) return;
76	    setMediaViewerPayload({
77	      roomId: room.id(),
78	      initialEventId: eventId,
79	      initialEvent: event,
80	    });
81	  };
82	
83	  return (
84	    <Block flex={1}>
85	      <Block flexDirection="row" margins={{ marginBottom: 16 }}>
86	        {(["media", "files"] as Tab[]).map((tab) => (
87	          <Button.Wrapper
88	            key={tab}
89	            onPress={() => setActiveTab(tab)}
90	            style={styles.tab}
91	          >
92	            <Block
93	              align="center"
94	              paddings={[10, 0]}
95	              border={{
96	                borderBottomWidth: 2,
97	                borderBottomColor:
98	                  activeTab === tab ? Colors.primary : Colors.white20,
99	              }}
100	            >
101	              <Text
102	                size={TextSize.small}
103	                color={activeTab === tab ? Colors.white : Colors.white50}
104	                textTransform="capitalize"
105	              >
106	                {tab}
107	              </Text>
108	            </Block>
109	          </Button.Wrapper>
110	        ))}
111	      </Block>
112	
113	      {activeTab === "media" ? (
114	        <Block flex={1}>
115	          <MediaList
116	            items={mediaItems}
117	            loading={loading}
118	            paginating={paginating}
119	            isEmpty={isMediaEmpty}
120	            onPressItem={handleSetActiveImageUri}
121	          />
122	        </Block>
123	      ) : (
124	        <FilesList
125	          items={fileItems}
126	          loading={loading}
127	          paginating={paginating}
128	          isEmpty={isFileEmpty}
129	        />
130	      )}
131	    </Block>
132	  );
133	};
134	
135	const styles = StyleSheet.create({
136	  tab: {
137	    flex: 1,
138	  },
139	});
